"""Sales totals by region."""
import csv


def main():
    totals = {}
    with open("sales.csv", newline="") as stream:
        for row in csv.DictReader(stream):
            totals[row["region"]] = totals.get(row["region"], 0) + int(row["amount"])
    with open("totals.csv", "w", newline="") as stream:
        stream.write("region,total\n")
        for region in sorted(totals):
            stream.write(f"{region},{totals[region]}\n")


if __name__ == "__main__":
    main()
